// An in-memory task store.
function normaliseTags(tags) {
  if (tags === undefined) return [];
  const seen = new Set();
  const result = [];
  for (const raw of tags) {
    const tag = String(raw).trim().toLowerCase();
    if (!tag || seen.has(tag)) continue;
    seen.add(tag);
    result.push(tag);
  }
  return result;
}

export function createStore() {
  const tasks = [];
  let nextId = 1;
  return {
    add(title, options = {}) {
      const task = {
        id: nextId++,
        title,
        done: false,
        tags: normaliseTags(options.tags),
      };
      tasks.push(task);
      return { ...task, tags: [...task.tags] };
    },
    complete(id) {
      const task = tasks.find((item) => item.id === id);
      if (!task) throw new Error('No task ' + id);
      task.done = true;
      return { ...task, tags: [...task.tags] };
    },
    list(options = {}) {
      const tag =
        options.tag === undefined ? undefined : String(options.tag).trim().toLowerCase();
      return tasks
        .filter((task) => tag === undefined || task.tags.includes(tag))
        .map((task) => ({ ...task, tags: [...task.tags] }));
    },
  };
}

export function formatTask(task) {
  const tags = task.tags ?? [];
  return (
    (task.done ? '[x]' : '[ ]') +
    ' ' +
    task.id +
    ' ' +
    task.title +
    tags.map((tag) => ' #' + tag).join('')
  );
}

import { formatTask } from './format.js';

// Reads the value that follows a --tag option.
function readTagValue(args, index) {
  const value = args[index + 1];
  if (value === undefined || value.startsWith('--')) {
    throw new Error('--tag needs a value');
  }
  return value;
}

// Splits argv into positional words and collected --tag values.
function parseArgs(args) {
  const words = [];
  const tags = [];
  for (let index = 0; index < args.length; index += 1) {
    const arg = args[index];
    if (arg === '--tag') {
      tags.push(readTagValue(args, index));
      index += 1;
    } else if (arg.startsWith('--')) {
      throw new Error('Unknown option: ' + arg);
    } else {
      words.push(arg);
    }
  }
  return { words, tags };
}

// Runs one command and returns the lines to print.
export function run(store, argv) {
  const [command, ...rest] = argv;
  if (command === 'add') {
    const { words, tags } = parseArgs(rest);
    return [formatTask(store.add(words.join(' '), { tags }))];
  }
  if (command === 'done') {
    const { words } = parseArgs(rest);
    return [formatTask(store.complete(Number(words[0])))];
  }
  if (command === 'list') {
    const { tags } = parseArgs(rest);
    return store.list({ tag: tags[0] }).map(formatTask);
  }
  throw new Error('Unknown command: ' + command);
}

