import test from 'node:test';
import assert from 'node:assert/strict';
import { createStore } from '../src/store.js';
import { formatTask } from '../src/format.js';
import { run } from '../src/cli.js';

test('add normalises tags and defaults to an empty array', () => {
  const store = createStore();
  const tagged = store.add('Buy milk', { tags: [' Home ', 'HOME', 'errand'] });
  assert.deepEqual(tagged.tags, ['home', 'errand']);
  assert.deepEqual(store.add('Plain').tags, []);
});

test('list filters by tag case-insensitively', () => {
  const store = createStore();
  store.add('Buy milk', { tags: ['home'] });
  store.add('Ship parcel', { tags: ['errand'] });
  store.add('Plain');
  assert.deepEqual(
    store.list({ tag: 'HOME' }).map((task) => task.title),
    ['Buy milk'],
  );
  assert.equal(store.list().length, 3);
});

test('formatTask appends tags after the title', () => {
  assert.equal(
    formatTask({ id: 1, title: 'Buy milk', done: false, tags: ['home', 'errand'] }),
    '[ ] 1 Buy milk #home #errand',
  );
  assert.equal(formatTask({ id: 2, title: 'Plain', done: true, tags: [] }), '[x] 2 Plain');
});

test('cli parses --tag for add and list', () => {
  const store = createStore();
  assert.deepEqual(run(store, ['add', 'Buy', 'milk', '--tag', 'home', '--tag', 'errand']), [
    '[ ] 1 Buy milk #home #errand',
  ]);
  run(store, ['add', 'Ship parcel', '--tag', 'errand']);
  assert.deepEqual(run(store, ['list', '--tag', 'home']), ['[ ] 1 Buy milk #home #errand']);
  assert.equal(run(store, ['list']).length, 2);
});

test('cli rejects unknown options and valueless --tag', () => {
  const store = createStore();
  assert.throws(() => run(store, ['add', 'x', '--x']), /^Error: Unknown option: --x$/);
  assert.throws(() => run(store, ['add', 'x', '--tag']), /^Error: --tag needs a value$/);
  assert.throws(() => run(store, ['list', '--tag']), /^Error: --tag needs a value$/);
});
